596		instanceMemoRelatedSetting, err := s.Store.GetInstanceMemoRelatedSetting(ctx)
597		if err != nil {
598			return 0, status.Errorf(codes.Internal, "failed to get instance memo related setting")
599		}
600		return int(instanceMemoRelatedSetting.ContentLengthLimit), nil
